-- ============================================================
-- 0003_sources_provenance.sql
-- ============================================================
-- StudyLab v0.2 — Phase 3: Sources & provenance
-- Every piece of content the student sees carries a 4-level source hierarchy:
--   1 — student / lecturer / university course material (their own uploads & links)
--   2 — authoritative academic source
--   3 — curated external resource (e.g. vetted videos)
--   4 — AI-generated (never presented as authoritative)
-- Adds `source_level` + `provenance` to content_resources, ingestion bookkeeping
-- to uploaded_materials, and the extracted_content table that a processor
-- (Edge Function) fills with structured items pulled from a student's documents.
--
-- Design notes:
-- * extracted_content rows are written by the server-side `process-material`
--   Edge Function (service role); students can only read rows of their own
--   materials. The original document is never modified — extraction is
--   derived, stored separately, and keeps page/confidence provenance.

-- ============================================================
-- Source hierarchy on shared content resources
-- ============================================================

alter table public.content_resources
  add column if not exists source_level integer check (source_level between 1 and 4);

alter table public.content_resources
  add column if not exists provenance jsonb not null default '{}'::jsonb;

-- ============================================================
-- Upload ingestion bookkeeping
-- ============================================================

alter table public.uploaded_materials
  add column if not exists processing_error text;

alter table public.uploaded_materials
  add column if not exists page_count integer;

-- ============================================================
-- Extracted content (derived from uploads; original untouched)
-- ============================================================

create table if not exists public.extracted_content (
  id uuid primary key default gen_random_uuid(),
  material_id uuid not null references public.uploaded_materials(id) on delete cascade,
  item_type text not null check (item_type in (
    'heading','definition','formula','example','question',
    'objective','activity','concept','relationship'
  )),
  content text not null,
  heading text,
  source_page integer,
  confidence numeric not null default 1 check (confidence between 0 and 1),
  concept_id uuid references public.concepts(id) on delete set null,
  question_id uuid references public.questions(id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists idx_extracted_content_material on public.extracted_content(material_id);
create index if not exists idx_extracted_content_concept on public.extracted_content(concept_id);
create index if not exists idx_extracted_content_question on public.extracted_content(question_id);

-- ============================================================
-- Row Level Security
-- ============================================================

alter table public.extracted_content enable row level security;

-- Students can read extracted items for materials they own.
drop policy if exists "students read own extracted content" on public.extracted_content;
create policy "students read own extracted content"
  on public.extracted_content for select to authenticated
  using (
    exists (
      select 1 from public.uploaded_materials m
      where m.id = material_id and m.student_id = auth.uid()
    )
  );

-- (Insert/update/delete for extracted_content are intentionally service-role
-- only: the processor Edge Function writes rows, students never fabricate
-- "extracted from your material" content.)

-- ============================================================
-- Grants (mirror the existing grants pattern from 0001)
-- ============================================================

grant select on public.extracted_content to authenticated;
grant insert, update, delete on public.extracted_content to service_role;


-- ============================================================
-- 0004_assessments_mastery.sql
-- ============================================================
-- StudyLab v0.2 — Phase 5+6: Assessment engine & concept-level mastery
-- * question_attempts now link to a learning_session and carry an
--   attempt_number (re-attempts of the same item inside a session).
-- * assessments: a titled set of questions (question_ids) with a pass mark
--   and optional time limit — authored per course/topic, gated by status.
-- * assessment_attempts: one row per student sitting, with per-question
--   results stored as jsonb so per-item review is possible.
-- * concept_mastery: mastery tracked at concept granularity (the engine
--   distinguishes easy vs application items; a student who passes easy
--   items but fails application items is capped at 'developing').
--
-- RLS: students own their attempts and mastery rows; assessments follow the
-- same status-gated read pattern as questions (review/approved visible to
-- students, writable only by their author while draft/review).

-- ============================================================
-- Question attempt enrichment
-- ============================================================

alter table public.question_attempts
  add column if not exists learning_session_id uuid;

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'question_attempts_learning_session_id_fkey'
  ) then
    alter table public.question_attempts
      add constraint question_attempts_learning_session_id_fkey
      foreign key (learning_session_id) references public.learning_sessions(id)
      on delete set null;
  end if;
end $$;

alter table public.question_attempts
  add column if not exists attempt_number integer not null default 1;

create index if not exists idx_question_attempts_session
  on public.question_attempts(learning_session_id);

-- ============================================================
-- Assessments
-- ============================================================

create table if not exists public.assessments (
  id uuid primary key default gen_random_uuid(),
  course_id uuid references public.courses(id) on delete set null,
  topic_id uuid references public.topics(id) on delete set null,
  title text not null,
  description text,
  question_ids jsonb not null default '[]'::jsonb,
  pass_percent numeric not null default 70 check (pass_percent between 0 and 100),
  time_limit_seconds integer check (time_limit_seconds is null or time_limit_seconds > 0),
  status text not null default 'draft' check (status in ('draft','review','approved','archived')),
  source_type text,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (course_id is not null or topic_id is not null)
);

create index if not exists idx_assessments_course on public.assessments(course_id);
create index if not exists idx_assessments_topic on public.assessments(topic_id);
create index if not exists idx_assessments_status on public.assessments(status);

-- ============================================================
-- Assessment attempts
-- ============================================================

create table if not exists public.assessment_attempts (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.student_profiles(id) on delete cascade,
  assessment_id uuid not null references public.assessments(id) on delete cascade,
  learning_session_id uuid references public.learning_sessions(id) on delete set null,
  started_at timestamptz not null default now(),
  submitted_at timestamptz,
  score numeric check (score between 0 and 100),
  passed boolean,
  question_results jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists idx_assessment_attempts_student
  on public.assessment_attempts(student_id, created_at desc);
create index if not exists idx_assessment_attempts_assessment
  on public.assessment_attempts(assessment_id);

-- ============================================================
-- Concept mastery
-- ============================================================

create table if not exists public.concept_mastery (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.student_profiles(id) on delete cascade,
  concept_id uuid not null references public.concepts(id) on delete cascade,
  mastery_score numeric not null default 0 check (mastery_score between 0 and 100),
  mastery_level text not null default 'not_assessed'
    check (mastery_level in ('not_assessed','weak','developing','strong','mastered')),
  confidence_score numeric not null default 0 check (confidence_score between 0 and 100),
  attempt_count integer not null default 0,
  last_assessed_at timestamptz,
  updated_at timestamptz not null default now(),
  unique(student_id, concept_id)
);

create index if not exists idx_concept_mastery_student on public.concept_mastery(student_id);
create index if not exists idx_concept_mastery_concept on public.concept_mastery(concept_id);

-- ============================================================
-- topic_mastery level vocabulary
-- The mastery engine writes not_assessed/weak/developing/strong/mastered;
-- widen the 0001 check constraint (which used a legacy vocabulary) so
-- upserts from the engine never violate it. Legacy values stay allowed.
-- ============================================================

do $$
begin
  if exists (
    select 1 from pg_constraint
    where conname = 'topic_mastery_mastery_level_check'
      and conrelid = 'public.topic_mastery'::regclass
  ) then
    alter table public.topic_mastery
      drop constraint topic_mastery_mastery_level_check;
  end if;
end $$;

alter table public.topic_mastery
  add constraint topic_mastery_mastery_level_check
  check (mastery_level in (
    'not_assessed','not_started','learning','weak',
    'developing','functional','strong','mastered'
  ));

-- ============================================================
-- updated_at triggers
-- ============================================================

do $$
declare t text;
begin
  foreach t in array array['assessments','concept_mastery']
  loop
    execute format('drop trigger if exists %I_updated_at on public.%I', t, t);
    execute format('create trigger %I_updated_at before update on public.%I for each row execute function public.set_updated_at()', t, t);
  end loop;
end $$;

-- ============================================================
-- Row Level Security
-- ============================================================

alter table public.assessments enable row level security;
alter table public.assessment_attempts enable row level security;
alter table public.concept_mastery enable row level security;

-- Students see published assessments; authors manage their own drafts.
drop policy if exists "authenticated read published assessments" on public.assessments;
create policy "authenticated read published assessments"
  on public.assessments for select to authenticated
  using (status in ('review','approved'));

drop policy if exists "students insert own assessments" on public.assessments;
create policy "students insert own assessments"
  on public.assessments for insert to authenticated
  with check (created_by = auth.uid() and status in ('draft','review'));

drop policy if exists "students update own assessments" on public.assessments;
create policy "students update own assessments"
  on public.assessments for update to authenticated
  using (created_by = auth.uid() and status in ('draft','review'))
  with check (created_by = auth.uid() and status in ('draft','review'));

drop policy if exists "students delete own assessments" on public.assessments;
create policy "students delete own assessments"
  on public.assessments for delete to authenticated
  using (created_by = auth.uid() and status in ('draft','review'));

drop policy if exists "students manage own assessment attempts" on public.assessment_attempts;
create policy "students manage own assessment attempts"
  on public.assessment_attempts for all to authenticated
  using (student_id = auth.uid())
  with check (student_id = auth.uid());

drop policy if exists "students manage own concept mastery" on public.concept_mastery;
create policy "students manage own concept mastery"
  on public.concept_mastery for all to authenticated
  using (student_id = auth.uid())
  with check (student_id = auth.uid());

-- ============================================================
-- Grants
-- ============================================================

grant select on public.assessments to authenticated;
grant insert, update, delete on public.assessments to authenticated;
grant select, insert, update, delete on public.assessments to service_role;

grant select, insert, update, delete on public.assessment_attempts to authenticated;
grant select, insert, update, delete on public.assessment_attempts to service_role;

grant select, insert, update, delete on public.concept_mastery to authenticated;
grant select, insert, update, delete on public.concept_mastery to service_role;


-- ============================================================
-- 0005_ai_reflection.sql
-- ============================================================
-- StudyLab v0.2 — Phase 8: AI reflection (Feynman explain-back)
-- Students explain a topic/concept in their own words. The response is
-- stored immediately; the server-side `ai-tutor` Edge Function evaluates it
-- and writes ai_feedback + score back (see 0005 grant for service_role).
-- Until evaluation runs, score is null and the UI shows "evaluation
-- pending" — no fake scores.

create table if not exists public.explain_back_attempts (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.student_profiles(id) on delete cascade,
  topic_id uuid references public.topics(id) on delete set null,
  concept_id uuid references public.concepts(id) on delete set null,
  prompt text not null,
  student_response text not null,
  ai_feedback jsonb,
  score numeric check (score between 0 and 100),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_explain_back_student
  on public.explain_back_attempts(student_id, created_at desc);
create index if not exists idx_explain_back_topic on public.explain_back_attempts(topic_id);
create index if not exists idx_explain_back_concept on public.explain_back_attempts(concept_id);

do $$
begin
  drop trigger if exists explain_back_attempts_updated_at on public.explain_back_attempts;
  create trigger explain_back_attempts_updated_at
    before update on public.explain_back_attempts
    for each row execute function public.set_updated_at();
end $$;

alter table public.explain_back_attempts enable row level security;

drop policy if exists "students manage own explain-back attempts" on public.explain_back_attempts;
create policy "students manage own explain-back attempts"
  on public.explain_back_attempts for all to authenticated
  using (student_id = auth.uid())
  with check (student_id = auth.uid());

grant select, insert, update, delete on public.explain_back_attempts to authenticated;
grant select, insert, update, delete on public.explain_back_attempts to service_role;


-- ============================================================
-- 0006_practical_activities.sql
-- ============================================================
-- StudyLab v0.2 — Phase 9: Practical learning activity attempts
-- Quick guided activities (equation balancer, break-even calculator, unit
-- converter, rate-of-change checker, …) are deterministic built-ins from
-- src/lib/practical-activities.ts. Completions are recorded here so practice
-- history is real and queryable — nothing is faked in the UI.

create table if not exists public.activity_attempts (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.student_profiles(id) on delete cascade,
  activity_type text not null,
  subject text,
  scenario jsonb not null default '{}'::jsonb,
  answer jsonb not null default '{}'::jsonb,
  is_correct boolean,
  score numeric check (score between 0 and 100),
  time_seconds integer,
  created_at timestamptz not null default now()
);

create index if not exists idx_activity_attempts_student
  on public.activity_attempts(student_id, created_at desc);
create index if not exists idx_activity_attempts_type on public.activity_attempts(activity_type);

alter table public.activity_attempts enable row level security;

drop policy if exists "students manage own activity attempts" on public.activity_attempts;
create policy "students manage own activity attempts"
  on public.activity_attempts for all to authenticated
  using (student_id = auth.uid())
  with check (student_id = auth.uid());

grant select, insert, update, delete on public.activity_attempts to authenticated;
grant select, insert, update, delete on public.activity_attempts to service_role;


-- ============================================================
-- 0007_own_draft_visibility.sql
-- ============================================================
-- StudyLab v0.2 — authors can see their own draft/review rows.
--
-- The 0001 read policy on questions exposes only status = 'approved' to all
-- students. That is correct for other people's drafts, but it also hides a
-- student's OWN draft questions from them — breaking the
-- author → practise → test-your-own-assessment loop (and making the
-- "include own drafts" query option a silent no-op).
--
-- Widen visibility to: published for everyone, plus anything the author
-- created. All other student data remains owner-scoped as before.

drop policy if exists "authenticated read approved questions" on public.questions;

drop policy if exists "authenticated read approved or own questions" on public.questions;
create policy "authenticated read approved or own questions"
  on public.questions for select to authenticated
  using (status = 'approved' or created_by = auth.uid());

drop policy if exists "authenticated read published assessments" on public.assessments;

drop policy if exists "authenticated read published or own assessments" on public.assessments;
create policy "authenticated read published or own assessments"
  on public.assessments for select to authenticated
  using (status in ('review', 'approved') or created_by = auth.uid());


-- ============================================================
-- 0008_live_readiness.sql
-- ============================================================
-- StudyLab 0008 — live readiness (merged with v0.2)
-- Apply AFTER 0007_own_draft_visibility.sql (i.e. after the full v0.2
-- migration set 0001-0007).
--
-- Merge notes:
-- * The topics/units/questions authoring policies this file used to
--   create are already owned by 0002 (and the questions read rule by
--   0007), so they are intentionally NOT re-created here.
-- * The `add column if not exists` statements below are idempotent
--   no-ops for columns v0.2 already added (e.g. learning_units.body).
-- * This file's practicals/steps/options/resources policies are new
--   and fill gaps v0.2 did not cover (e.g. topic_resources had no
--   insert policy, so linking resources to topics needed this).

-- ---------------------------------------------------------------
-- 1.  Add columns introduced by the current app that were not in
--     the v0.1 migration.
-- ---------------------------------------------------------------
alter table public.study_sessions
  add column if not exists topic_id uuid references public.topics(id) on delete set null,
  add column if not exists note text;

alter table public.learning_units
  add column if not exists body text;

alter table public.content_resources
  add column if not exists source_type text;

-- Student-added curriculum ownership (lets students author their own
-- topics/units/questions while shared curriculum remains read-only).
alter table public.topics                add column if not exists created_by uuid references auth.users(id) on delete set null;
alter table public.subtopics             add column if not exists created_by uuid references auth.users(id) on delete set null;
alter table public.learning_units        add column if not exists created_by uuid references auth.users(id) on delete set null;
alter table public.questions             add column if not exists created_by uuid references auth.users(id) on delete set null;
alter table public.question_options      add column if not exists created_by uuid references auth.users(id) on delete set null;
alter table public.practicals            add column if not exists created_by uuid references auth.users(id) on delete set null;
alter table public.practical_steps       add column if not exists created_by uuid references auth.users(id) on delete set null;
alter table public.skills                add column if not exists created_by uuid references auth.users(id) on delete set null;
alter table public.content_resources     add column if not exists created_by uuid references auth.users(id) on delete set null;

-- ---------------------------------------------------------------
-- 2.  RLS additions that v0.2 does not already provide.
--     (Topics/units/questions authoring rules live in 0002; the
--     questions "approved or own" read rule lives in 0007.)
-- ---------------------------------------------------------------

drop policy if exists "students insert own subtopics" on public.subtopics;
create policy "students insert own subtopics" on public.subtopics for insert to authenticated with check (created_by = auth.uid());
drop policy if exists "students manage own subtopics" on public.subtopics;
create policy "students manage own subtopics" on public.subtopics for update to authenticated using (created_by = auth.uid()) with check (created_by = auth.uid());
drop policy if exists "students delete own subtopics" on public.subtopics;
create policy "students delete own subtopics" on public.subtopics for delete to authenticated using (created_by = auth.uid());

-- Students can read all approved units plus their own drafts.
drop policy if exists "authenticated read learning units" on public.learning_units;
drop policy if exists "authenticated read learning units" on public.learning_units;
create policy "authenticated read learning units" on public.learning_units
  for select to authenticated using (status = 'approved' or created_by = auth.uid());

drop policy if exists "students insert own options" on public.question_options;
create policy "students insert own options"   on public.question_options for insert to authenticated with check (created_by = auth.uid());
drop policy if exists "students manage own options" on public.question_options;
create policy "students manage own options"   on public.question_options for update to authenticated using (created_by = auth.uid()) with check (created_by = auth.uid());
drop policy if exists "students delete own options" on public.question_options;
create policy "students delete own options"   on public.question_options for delete to authenticated using (created_by = auth.uid());
drop policy if exists "authenticated read question options" on public.question_options;
drop policy if exists "authenticated read question options" on public.question_options;
create policy "authenticated read question options" on public.question_options
  for select to authenticated using (
    exists (select 1 from public.questions q where q.id = question_id and (q.status = 'approved' or q.created_by = auth.uid()))
  );

drop policy if exists "students insert own practicals" on public.practicals;
create policy "students insert own practicals" on public.practicals for insert to authenticated with check (created_by = auth.uid());
drop policy if exists "students manage own practicals" on public.practicals;
create policy "students manage own practicals" on public.practicals for update to authenticated using (created_by = auth.uid()) with check (created_by = auth.uid());
drop policy if exists "students delete own practicals" on public.practicals;
create policy "students delete own practicals" on public.practicals for delete to authenticated using (created_by = auth.uid());
drop policy if exists "authenticated read practicals" on public.practicals;
drop policy if exists "authenticated read practicals" on public.practicals;
create policy "authenticated read practicals" on public.practicals
  for select to authenticated using (status = 'approved' or created_by = auth.uid());

drop policy if exists "students insert own practical steps" on public.practical_steps;
create policy "students insert own practical steps" on public.practical_steps for insert to authenticated with check (created_by = auth.uid());
drop policy if exists "students manage own practical steps" on public.practical_steps;
create policy "students manage own practical steps" on public.practical_steps for update to authenticated using (created_by = auth.uid()) with check (created_by = auth.uid());
drop policy if exists "students delete own practical steps" on public.practical_steps;
create policy "students delete own practical steps" on public.practical_steps for delete to authenticated using (created_by = auth.uid());
drop policy if exists "authenticated read practical steps" on public.practical_steps;
drop policy if exists "authenticated read practical steps" on public.practical_steps;
create policy "authenticated read practical steps" on public.practical_steps
  for select to authenticated using (
    exists (select 1 from public.practicals p where p.id = practical_id and (p.status = 'approved' or p.created_by = auth.uid()))
  );

-- Skills + content resources: students author their own, shared ones are readable.
drop policy if exists "students insert own skills" on public.skills;
create policy "students insert own skills"    on public.skills for insert to authenticated with check (created_by = auth.uid());
drop policy if exists "students manage own skills" on public.skills;
create policy "students manage own skills"    on public.skills for update to authenticated using (created_by = auth.uid()) with check (created_by = auth.uid());
drop policy if exists "students insert own resources" on public.content_resources;
create policy "students insert own resources" on public.content_resources for insert to authenticated with check (created_by = auth.uid());
drop policy if exists "students manage own resources" on public.content_resources;
create policy "students manage own resources" on public.content_resources for update to authenticated using (created_by = auth.uid()) with check (created_by = auth.uid());
drop policy if exists "students delete own resources" on public.content_resources;
create policy "students delete own resources" on public.content_resources for delete to authenticated using (created_by = auth.uid());
drop policy if exists "students link own resources" on public.topic_resources;
create policy "students link own resources"   on public.topic_resources for insert to authenticated with check (true);

-- ---------------------------------------------------------------
-- 3.  Optional: storage for uploaded materials is already
--     created in 0001.  Add a max-size guard (10 MB) for safety.
-- ---------------------------------------------------------------
