-- Questions
insert into public.questions (id, topic_id, subtopic_id, question_type, difficulty, question_text, explanation, hint_1, hint_2, correct_answer, estimated_seconds, status, created_by) values
  ('1f82cd51-2eba-5836-87c6-ea5818006706', '4b64262f-0eca-5ba5-bca0-e7aac67781f3', 'a36a2f5e-47e6-5f1b-a612-83bdb4dc57d6', 'numeric', 1, 'Evaluate lim x→2 (3x + 1).', 'By direct substitution, 3(2)+1 = 7.', null, null, '{"number":7}'::jsonb, 90, 'approved', null),
  ('f4bb8564-5403-5262-b11c-a6d0bb780a5d', '4b64262f-0eca-5ba5-bca0-e7aac67781f3', 'a36a2f5e-47e6-5f1b-a612-83bdb4dc57d6', 'true_false', 1, 'The limit lim x→a f(x) requires f(a) to be defined.', 'A limit depends only on behaviour near a, not on f(a).', null, null, '{"key":"false"}'::jsonb, 90, 'approved', null),
  ('366ca24d-425f-5ec3-a1b1-0f2e9b8d3be1', '4b64262f-0eca-5ba5-bca0-e7aac67781f3', 'a36a2f5e-47e6-5f1b-a612-83bdb4dc57d6', 'multiple_choice', 2, 'lim x→1 (x²−1)/(x−1) equals:', 'Factor as (x−1)(x+1)/(x−1) = x+1, which approaches 2.', 'Factor the numerator.', null, '{"key":"C"}'::jsonb, 90, 'approved', null),
  ('0de5103d-5d45-5daa-bc2a-69ebef40203f', '4b64262f-0eca-5ba5-bca0-e7aac67781f3', 'aba27331-965f-591f-8a00-746cdfca3207', 'multiple_choice', 2, 'Which condition is NOT required for continuity at a?', 'Differentiability is stronger than continuity; continuity does not require it.', null, null, '{"key":"D"}'::jsonb, 90, 'approved', null),
  ('6cefefde-c8f4-538a-9f92-b766f1c38ed2', '6da11359-3901-5ab6-80fe-4a36571bf41d', '2a664186-035b-5a3b-8a99-cd5c47185511', 'multiple_choice', 1, 'The derivative measures:', 'The derivative is the instantaneous rate of change.', null, null, '{"key":"B"}'::jsonb, 90, 'approved', null),
  ('9a78b6ff-e633-5db5-b4ed-9dcf851ca68c', '6da11359-3901-5ab6-80fe-4a36571bf41d', '2a664186-035b-5a3b-8a99-cd5c47185511', 'multiple_choice', 2, 'If f(x)=3x²+2x, f''(x)=', 'Differentiate term by term: 6x + 2.', null, null, '{"key":"A"}'::jsonb, 90, 'approved', null),
  ('878824cf-c519-5b76-ba3d-0a24b2bed656', 'fdb024fc-0c18-555d-b6b3-96782f5ab803', 'c7e56f84-028c-52ba-852b-902a4b0bd5e7', 'true_false', 2, 'L''Hôpital''s rule applies to 0/0 and ∞/∞ forms.', 'These are the standard indeterminate forms it handles.', null, null, '{"key":"true"}'::jsonb, 90, 'approved', null),
  ('6c7735a0-b062-51e5-b4bd-4f47ed7b4457', '5da94c7c-05ee-5962-8205-23a3cdb1f7d7', '8f816d37-5550-5f4a-83ea-2ba5d3e329ab', 'multiple_choice', 1, 'A fair die rolls. P(even) =', 'Three even faces out of six = 1/2.', null, null, '{"key":"C"}'::jsonb, 90, 'approved', null),
